### 8. Create `Components/StarRating.razor` (Interactive Server component)
This is the interactive rating widget. It MUST have `@rendermode InteractiveServer`.

```razor
@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => Rate(star)"
                title="Rate @star star(s)"
                disabled="@HasRated">
            @(star <= _hoveredStar ? "★" : "☆")
        </button>
    }

    @if (HasRated)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int _hoveredStar;
    private bool HasRated;

    private void Rate(int stars)
    {
        if (HasRated) return;
        RecipeService.AddRating(RecipeId, stars);
        _hoveredStar = stars;
        HasRated = true;
    }
}
```

