@page "/recipes"
@page "/recipes/{CategoryName}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(CategoryName ?? "All Categories") — RecipeShare</PageTitle>

@if (string.IsNullOrEmpty(CategoryName))
{
    <h1>Recipe Categories</h1>
    <div class="list-group">
        @foreach (var category in RecipeService.GetCategories())
        {
            <a href="/recipes/@Uri.EscapeDataString(category)" class="list-group-item list-group-item-action">
                <strong>@category</strong>
                <span class="badge bg-secondary float-end">@RecipeService.GetByCategory(category).Count</span>
            </a>
        }
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/recipes">All Categories</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    var recipes = RecipeService.GetByCategory(CategoryName);

    @if (recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4">
            @foreach (var recipe in recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                            @if (recipe.RatingCount > 0)
                            {
                                <small class="text-muted">
                                    ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                                </small>
                            }
                        </div>
                        <div class="card-footer">
                            <a href="/recipes/detail/@recipe.Id" class="btn btn-outline-primary btn-sm">
                                View Recipe
                            </a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategoryName { get; set; }
}

@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => Rate(star)"
                title="Rate @star star(s)"
                disabled="@HasRated">
            @(star <= _hoveredStar ? "★" : "☆")
        </button>
    }

    @if (HasRated)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int _hoveredStar;
    private bool HasRated;

    private void Rate(int stars)
    {
        if (HasRated) return;
        RecipeService.AddRating(RecipeId, stars);
        _hoveredStar = stars;
        HasRated = true;
    }
}

@page "/recipes/detail/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/recipes" class="btn btn-secondary">Back to Recipes</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/recipes">All Categories</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@Uri.EscapeDataString(recipe.Category)">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>

    @if (recipe.RatingCount > 0)
    {
        <p>⭐ @recipe.AverageRating.ToString("F1") average — @recipe.RatingCount rating(s)</p>
    }

    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="recipe.Id" />

    <hr />

    <h3>Ingredients</h3>
    <ul class="list-group list-group-flush mb-4">
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol class="list-group list-group-numbered mb-4">
        @foreach (var step in recipe.Steps)
        {
            <li class="list-group-item">@step</li>
        }
    </ol>

    <a href="/recipes/@Uri.EscapeDataString(recipe.Category)" class="btn btn-secondary">
        ← Back to @recipe.Category
    </a>
}

