```razor
@page "/recipes"
@page "/recipes/{CategoryName}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(CategoryName ?? "All Categories") — RecipeShare</PageTitle>

@if (string.IsNullOrEmpty(CategoryName))
{
    <h1>Recipe Categories</h1>
    <div class="list-group">
        @foreach (var category in RecipeService.GetCategories())
        {
            <a href="/recipes/@Uri.EscapeDataString(category)" class="list-group-item list-group-item-action">
                <strong>@category</strong>
                <span class="badge bg-secondary float-end">@RecipeService.GetByCategory(category).Count</span>
            </a>
        }
    </div>
}
else
{
